using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: index i holds the bit-reversal of byte i.
    private static readonly byte[] LookupTable = BuildLookupTable();

    private static byte[] BuildLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int reversed = 0;
            int val = i;
            for (int bit = 0; bit < 8; bit++)
            {
                reversed = (reversed << 1) | (val & 1);
                val >>= 1;
            }
            table[i] = (byte)reversed;
        }
        return table;
    }

    // SIMD nibble-reverse lookup: reversing bits within each nibble.
    // Index n maps to the 4-bit reversal of n, already shifted into the high nibble.
    private static readonly Vector256<byte> NibbleReverseHi = Vector256.Create(
        (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
              0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0,
              0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
              0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);

    // Same table but results in low nibble position.
    private static readonly Vector256<byte> NibbleReverseLo = Vector256.Create(
        (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
              0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F,
              0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
              0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

    private static readonly Vector256<byte> LowNibbleMask = Vector256.Create((byte)0x0F);

    public static void ReverseInPlace(Span<byte> data)
    {
        if (Vector256.IsHardwareAccelerated)
        {
            ReverseSimd256(data);
        }
        else if (Vector128.IsHardwareAccelerated)
        {
            ReverseSimd128(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseSimd256(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector256<byte>.Count;

        // Process 32 bytes at a time.
        while (i <= lastBlockStart)
        {
            var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);

            // Split each byte into its two nibbles, reverse each via shuffle,
            // then swap their positions (lo nibble reversed → hi, hi → lo).
            var lo = vec & LowNibbleMask;
            var hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & LowNibbleMask;

            var resultHi = Vector256.Shuffle(NibbleReverseHi, lo);
            var resultLo = Vector256.Shuffle(NibbleReverseLo, hi);

            (resultHi | resultLo).StoreUnsafe(ref ptr, (nuint)i);
            i += Vector256<byte>.Count;
        }

        // Scalar tail.
        byte[] table = LookupTable;
        for (; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = table[Unsafe.Add(ref ptr, i)];
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseSimd128(Span<byte> data)
    {
        var nibRevHi128 = NibbleReverseHi.GetLower();
        var nibRevLo128 = NibbleReverseLo.GetLower();
        var mask128 = LowNibbleMask.GetLower();

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector128<byte>.Count;

        while (i <= lastBlockStart)
        {
