            var resultLo = Vector128.Shuffle(nibRevLo128, hi);

            (resultHi | resultLo).StoreUnsafe(ref ptr, (nuint)i);
            i += Vector128<byte>.Count;
        }

        byte[] table = LookupTable;
        for (; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = table[Unsafe.Add(ref ptr, i)];
        }
    }

    private static void ReverseScalar(Span<byte> data)
    {
