using System;
using ByteBitReverse;

// Correctness test: compare SIMD path against known multiply-mod reference.
byte ReverseBitsRef(byte b) => (byte)((b * 0x0202020202UL & 0x010884422010UL) % 1023);

// Test all 256 byte values
var buf = new byte[256];
for (int i = 0; i < 256; i++) buf[i] = (byte)i;
var expected = new byte[256];
for (int i = 0; i < 256; i++) expected[i] = ReverseBitsRef((byte)i);

BitReverser.ReverseInPlace(buf);
bool pass = true;
for (int i = 0; i < 256; i++)
{
    if (buf[i] != expected[i]) { Console.WriteLine($"FAIL at {i}: got {buf[i]:X2}, expected {expected[i]:X2}"); pass = false; }
}

// Test 64KB buffer
var big = new byte[65536];
var rng = new Random(42);
rng.NextBytes(big);
var bigExpected = new byte[65536];
for (int i = 0; i < big.Length; i++) bigExpected[i] = ReverseBitsRef(big[i]);
BitReverser.ReverseInPlace(big);
for (int i = 0; i < big.Length; i++)
{
    if (big[i] != bigExpected[i]) { Console.WriteLine($"FAIL at big[{i}]"); pass = false; break; }
}

